'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cart=[];try{const saved=JSON.parse(localStorage.getItem('perritual-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(i=>Catalog.some(p=>p.id===i.id)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=20&&i.options&&typeof i.key==='string').slice(0,40)}catch{}
let filter='Todos', currentProduct=null, editKey=null, draft={},delivery={mode:'delivery',city:'Medellín',date:'',time:'',name:'',phone:'',address:'',note:'',consent:false},checkoutStep=1;
const colors={Durazno:'#e4a184',Salvia:'#8b9d7d',Lavanda:'#b4a3c5',Vainilla:'#ead99e'};
function art(type,o={}){const map={cake:'torta',kit:'kit',cupcake:'cupcakes',biscuit:'galletas',toy:'juguete',gift:'regalo'},id=map[type]||'torta',color=colors[o.color]||colors.Durazno;return `<div class="personal-preview" style="--chosen:${color}"><img src="${id}.webp" alt="Fotografía conceptual de ${esc(Catalog.find(p=>p.id===id).name)}" width="1024" height="1024"><div class="personal-tag"><span>HECHO PARA</span><strong>${esc(o.name||'Tu mejor amigo')}</strong><small>${o.age?esc(o.age)+' años · ':''}${esc(o.color||'Durazno')}${o.size?' · '+esc(o.size):''}</small></div></div>`}
// Keep feedback inside the active modal for accessibility, then lift it above
// the native dialog with a manual popover. z-index alone cannot cross top layers.
function dismissToast(){const n=$('#toast');clearTimeout(toast.timer);n.classList.remove('show');if(n.hidePopover)try{n.hidePopover()}catch{}}
function toast(t){
 const n=$('#toast');dismissToast();
 const host=$$('dialog[open]').at(-1)||document.body;
 if(n.parentElement!==host)host.append(n);
 n.textContent=t;n.classList.add('show');
 if(n.showPopover)try{n.showPopover()}catch{}
 toast.timer=setTimeout(dismissToast,5000);
}
$$('dialog').forEach(d=>d.addEventListener('close',()=>{if(!d.open&&d.contains($('#toast')))dismissToast()}));

function persist(){try{localStorage.setItem('perritual-cart-v1',JSON.stringify(cart))}catch{toast('El navegador no permite guardar la bolsa. Puedes continuar en esta sesión.')}$('#count').textContent=cart.reduce((n,i)=>n+i.qty,0)}
function renderProducts(){const query=$('#search').value.toLocaleLowerCase('es');const list=Catalog.filter(p=>(filter==='Todos'||p.category===filter)&&(p.name+' '+p.category+' '+p.desc).toLocaleLowerCase('es').includes(query));$('#products').innerHTML=list.map(p=>`<article class="product-card"><button class="product-art" style="--cardbg:${p.bg}" data-product="${p.id}" aria-label="Ver y personalizar ${p.name}">${productPhoto(p.id,p.name)}<span class="art-plus" aria-hidden="true">↗</span></button><div class="product-meta"><div><h3><a href="#${p.id}" data-product="${p.id}">${p.name}</a></h3><p>${p.desc}</p></div><div class="price">${Money(p.price)}${p.old?`<span class="old-price">${Money(p.old)}</span>`:''}</div></div></article>`).join('')||'<div class="no-results"><h3>No encontramos ese regalo.</h3><p>Prueba otra palabra o explora todas las categorías.</p><button class="btn secondary" id="resetSearch">Ver todos los regalos</button></div>';}
function renderFilters(){$('#filters').innerHTML=['Todos','Tortas','Kits','Cupcakes','Galletas','Juguetes','Regalos'].map(c=>`<button class="filter ${filter===c?'active':''}" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}
function opts(values,current){return values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function openProduct(id,key=null){const p=Catalog.find(p=>p.id===id);if(!p)return;currentProduct=p;editKey=key;const existing=cart.find(i=>i.key===key);draft=existing?{...existing.options}:{name:'',age:'1',size:'Pequeña',flavor:'Pollo y zanahoria',color:'Durazno',decoration:'Huesitos',message:'',toy:false};if($('#cartDialog').open)$('#cartDialog').close();$('#productContent').innerHTML=`<div class="product-detail"><div class="detail-visual" style="background:${p.bg}"><div id="liveArt">${art(p.type,draft)}</div><p>Vista previa conceptual.<br>La tarjeta refleja tu selección; la fotografía no reproduce el acabado final.</p></div><form id="productForm" class="detail-form"><h2 id="productTitle">${p.name}</h2><p class="desc">${p.detail}</p>${p.custom?`<div class="fields"><label>Nombre del perro<input name="name" maxlength="22" placeholder="Ej. Milo" value="${esc(draft.name)}" required></label><label>Edad que celebra<input type="number" name="age" min="0" max="30" step="1" value="${esc(draft.age)}" required></label>${['torta','kit'].includes(id)?`<label>Tamaño<select name="size">${opts(['Pequeña','Mediana','Grande'],draft.size)}</select></label>`:''}${id!=='regalo'?`<label>Sabor de ejemplo<select name="flavor">${opts(['Pollo y zanahoria','Banano y avena'],draft.flavor)}</select></label><label>Decoración<select name="decoration">${opts(['Huesitos','Flores'],draft.decoration)}</select></label>`:''}<div class="full"><label>Paleta de color</label><div class="swatches">${Object.entries(colors).map(([c,v])=>`<button type="button" class="swatch" data-color="${c}" style="--swatch:${v}" aria-label="${c}" aria-pressed="${draft.color===c}"></button>`).join('')}</div><small id="colorName">${esc(draft.color)}</small></div><label class="full">Tu dedicatoria <span class="muted">(opcional)</span><input name="message" maxlength="100" value="${esc(draft.message)}" placeholder="Que nunca te falten motivos para mover la cola"></label>${id==='kit'?`<label class="check full"><input type="checkbox" name="toy" ${draft.toy?'checked':''}>Añadir un juguete · +${Money(25000)}</label>`:''}</div>`:''}<div class="detail-total"><span>Valor de ejemplo</span><strong id="draftPrice">${Money(Rules.unit({id,options:draft}))}</strong></div><button class="btn primary" type="submit">${key?'Guardar cambios':'Añadir a su bolsa'} <span>↗</span></button><details><summary>Lo que debes saber de este producto</summary><p>${id==='juguete'?'Materiales, medidas y recomendaciones de uso pendientes de definir.':'Ingredientes, tamaño en gramos, porciones, restricciones alimentarias, conservación y vencimiento pendientes de validar. Los sabores son ejemplos, no recetas aprobadas.'} Los precios y beneficios de esta maqueta no constituyen una oferta comercial.</p></details></form></div>`;openDialog($('#productDialog'));$('#productForm').addEventListener('input',updateDraft);$('#productForm').addEventListener('change',updateDraft);$('#productForm').addEventListener('submit',e=>{e.preventDefault();updateDraft();if(p.custom&&!draft.name.trim()){toast('Escribe el nombre del perro.');return}if(cart.length>=40&&!key){toast('La bolsa de demostración admite hasta 40 referencias.');return}if(key){const i=cart.find(i=>i.key===key);if(i)i.options={...draft}}else cart.push({key:crypto.randomUUID(),id,qty:1,options:{...draft}});persist();$('#productDialog').close();renderCart();openDialog($('#cartDialog'));toast(key?'Personalización actualizada':'Un nuevo detalle en su bolsa ♡')})}
function productPhoto(id,name){return `<img src="${id}.webp" alt="Imagen conceptual de ${esc(name)}" loading="lazy" width="1024" height="1024">`}
function openDialog(el){dismissToast();if(!el.open)el.showModal()}
function closeDialog(el){dismissToast();el.close()}
function updateDraft(){const f=$('#productForm');if(currentProduct.custom){for(const key of ['name','age','size','flavor','decoration','message'])if(f.elements[key])draft[key]=f.elements[key].value;if(f.elements.toy)draft.toy=f.elements.toy.checked}$('#liveArt').innerHTML=art(currentProduct.type,draft);$('#draftPrice').textContent=Money(Rules.unit({id:currentProduct.id,options:draft}))}
function itemDescription(i){const p=Catalog.find(p=>p.id===i.id);if(!p.custom)return p.desc;const o=i.options;return [o.name,`${o.age} años`,['torta','kit'].includes(i.id)?o.size:'',i.id!=='regalo'?o.flavor:'',o.color,i.id!=='regalo'?o.decoration:'',o.toy?'Con juguete':'',o.message?`«${o.message}»`:''].filter(Boolean).join(' · ')}
function totalsHTML(t,final=false){return `<div class="totals"><div class="total-row"><span>Subtotal</span><span>${Money(t.subtotal)}</span></div>${t.discount?`<div class="total-row saving"><span>Beneficio de ejemplo · 10%</span><span>−${Money(t.discount)}</span></div>`:''}<div class="total-row"><span>Envío / recogida</span><span>${t.shipping===null?'Se calcula al programar':t.shipping===0?'Sin costo':Money(t.shipping)}</span></div><div class="total-row"><span>Impuestos</span><span>Incluidos en precio demo</span></div><div class="total-row grand"><span>${final?'Total estimado':'Total de productos'}</span><span>${Money(t.total)}</span></div></div>`}
function recommendationsHTML(){
 const ideas=Rules.recommendations(cart);if(!ideas.length)return '';
 return `<section class="goal-suggestions" aria-labelledby="suggestionTitle"><h3 id="suggestionTitle">${ideas[0].unlocks?'Completa su ritual y gana envío gratis':'Un detalle más para su celebración'}</h3><p class="suggestion-intro">${ideas[0].unlocks?'Elige una opción. El total ya contempla el descuento.':'Estos complementos te acercan al beneficio.'}</p>${ideas.map((r,index)=>`<article class="goal-option"><div class="suggestion-products">${r.lines.map(line=>{const p=Catalog.find(p=>p.id===line.id);return `<div class="suggestion-product"><img src="${p.id}.webp" alt="" width="52" height="52" loading="lazy"><div><strong>${line.qty} × ${p.name}</strong><small>${p.id==='cupcakes'?`${line.qty*4} cupcakes · detalles de ${esc(line.options.name)}`:p.id==='galletas'?`${line.qty*6} galletas adicionales`:'Un juguete adicional'}</small></div></div>`}).join('')}</div><div class="suggestion-outcome"><span>${r.unlocks?'Envío gratis al añadir esta opción':`Después te faltan ${Money(r.after.toAddForFree)} en productos`}</span><p>Tu total de productos: <strong>${Money(r.after.net)}</strong></p>${r.after.discount?`<small>Descuento incluido: ${Money(r.after.discount)}</small>`:''}</div><button class="btn secondary goal-add" data-goal="${index}">Añadir ${r.lines.reduce((n,l)=>n+l.qty,0)>1?'combinación':'complemento'} · ${Money(r.added)} <span aria-hidden="true">+</span></button></article>`).join('')}<p class="muted">${ideas.some(r=>r.lines.some(l=>l.id==='cupcakes'))?'Los cupcakes toman el nombre, la edad, el sabor y el color del primer producto personalizado de la bolsa. Puedes editarlos al añadirlos. ':''}Precios y beneficios de demostración.</p></section>`;
}
function renderCart(){const t=Rules.totals(cart);$('#cartContent').innerHTML=`<div class="cart-inner">${!cart.length?'<div class="empty"><span>♡</span><h3>Un ritual por comenzar</h3><p>Su próximo momento favorito te está esperando.</p><button class="btn primary" data-close="cartDialog">Explorar regalos ↗</button></div>':`<div class="reward">${t.toFree?`Agrega <strong>${Money(t.toAddForFree)}</strong> en productos para alcanzar el envío gratis.`:'¡Su celebración tiene envío gratis!'}<progress value="${Math.min(t.net,180000)}" max="180000" aria-label="Progreso hacia envío gratis"></progress><small>Ya calculamos el 10% de descuento que se activa desde $150.000. Envío gratis con $180.000 finales en productos. Beneficios de ejemplo.</small></div>${cart.map(i=>{const p=Catalog.find(p=>p.id===i.id);return `<article class="cart-line"><div class="cart-thumb">${productPhoto(p.id,p.name)}</div><div><h3>${p.name}</h3><p>${esc(itemDescription(i))}</p><div class="line-actions"><div class="qty"><button data-qty="${i.key}" data-delta="-1" aria-label="Restar una unidad de ${p.name}" ${i.qty<=1?'disabled':''}>−</button><span>${i.qty}</span><button data-qty="${i.key}" data-delta="1" aria-label="Sumar una unidad de ${p.name}" ${i.qty>=20?'disabled':''}>+</button></div><strong>${Money(Rules.unit(i)*i.qty)}</strong></div><div>${p.custom?`<button class="text-button" data-edit="${i.key}">Personalizar</button>`:''}<button class="text-button" data-remove="${i.key}">Eliminar</button></div></div></article>`}).join('')}${recommendationsHTML()}${totalsHTML(t)}<button class="btn primary" id="startCheckout">Programar su celebración <span>↗</span></button><p class="muted" style="text-align:center;margin-top:12px">Sin cobros · Cierre simulado por WhatsApp</p>`}</div>`}
function syncDelivery(){const f=$('#deliveryForm');if(!f)return;for(const k of ['city','date','time','name','phone','address','note'])if(f.elements[k])delivery[k]=f.elements[k].value;delivery.consent=f.elements.consent?.checked||false}
function renderCheckout(step){checkoutStep=step;$$('.progress-steps span').forEach((s,i)=>s.classList.toggle('active',i+1===step));const t=Rules.totals(cart,delivery);if(step===1){$('#checkoutContent').innerHTML=`<form id="deliveryForm"><div class="delivery-choices"><button type="button" data-mode="delivery" class="${delivery.mode==='delivery'?'active':''}" aria-pressed="${delivery.mode==='delivery'}">⌁ A domicilio</button><button type="button" data-mode="pickup" class="${delivery.mode==='pickup'?'active':''}" aria-pressed="${delivery.mode==='pickup'}">♡ Recoger</button></div><div class="fields">${delivery.mode==='delivery'?`<label>Municipio<select name="city">${opts(Object.keys(Regions),delivery.city)}</select></label><label>Dirección y barrio<input name="address" autocomplete="street-address" maxlength="160" value="${esc(delivery.address)}" placeholder="Ej. Calle 10 # 40-20, El Poblado" required></label>`:'<p class="muted full">Punto de recogida por acordar con el equipo. En esta maqueta no hay una dirección comercial confirmada.</p>'}<label>Fecha de celebración<input type="date" name="date" min="${Rules.minDate()}" value="${esc(delivery.date)}" required></label><label>Hora de entrega<select name="time" required><option value="">Selecciona una hora</option>${['10:00','14:00','17:00'].map(h=>`<option value="${h}" ${delivery.time===h?'selected':''}>${h} · hora Colombia</option>`).join('')}</select></label><p class="muted full">Mínimo 24 horas exactas de anticipación. Horarios ilustrativos, sujetos a confirmación.</p><label>Tu nombre<input name="name" autocomplete="name" maxlength="70" value="${esc(delivery.name)}" placeholder="Ej. Laura Gómez" required></label><label>Tu celular<input type="tel" name="phone" inputmode="tel" autocomplete="tel" maxlength="20" value="${esc(delivery.phone)}" placeholder="300 123 4567" pattern="[+0-9 ()-]{7,20}" required></label><label class="full">Algo que debamos saber <span class="muted">(opcional)</span><textarea name="note" maxlength="300" placeholder="Indicaciones de entrega o preguntas sobre ingredientes">${esc(delivery.note)}</textarea></label><label class="check full"><input name="consent" type="checkbox" ${delivery.consent?'checked':''} required>Entiendo que estoy probando una maqueta y que no se reserva ni se compra ningún producto.</label></div><p class="muted">Puedes usar datos ficticios. Este formulario se mantiene solo en memoria durante tu visita.</p><p class="error" id="deliveryError" role="alert"></p><div class="checkout-actions"><button class="btn secondary" type="button" id="backToCart">← Volver a la bolsa</button><button class="btn primary" type="submit">Revisar pedido ↗</button></div></form>`;$('#deliveryForm').addEventListener('submit',e=>{e.preventDefault();syncDelivery();if(!delivery.name.trim()||(delivery.mode==='delivery'&&!delivery.address.trim())){$('#deliveryError').textContent='Completa el nombre y la dirección.';return}if(!Rules.validSlot(delivery.date,delivery.time)){$('#deliveryError').textContent='Elige una fecha y hora con al menos 24 horas de anticipación desde este momento (hora Colombia).';$('#deliveryError').setAttribute('tabindex','-1');$('#deliveryError').focus();return}renderCheckout(2)});$('#deliveryForm').addEventListener('input',syncDelivery)}
if(step===2){$('#checkoutContent').innerHTML=`<p class="muted">Revisa los detalles. Todos los valores son de ejemplo y no se realizará un cobro.</p>${cart.map(i=>`<div class="review-box"><h3>${i.qty} × ${Catalog.find(p=>p.id===i.id).name}</h3><p>${esc(itemDescription(i))}</p><strong>${Money(Rules.unit(i)*i.qty)}</strong></div>`).join('')}<div class="review-box"><h3>${delivery.mode==='delivery'?'A domicilio':'Recogida por acordar'}</h3><p>${esc(delivery.date)} · ${esc(delivery.time)} (Colombia)
${delivery.mode==='delivery'?esc(delivery.city+' · '+delivery.address):'El equipo confirmaría el punto de recogida.'}
${esc(delivery.name)} · ${esc(delivery.phone)}${delivery.note?'\n'+esc(delivery.note):''}</p><button class="text-button" id="editDelivery">Editar entrega</button></div>${totalsHTML(t,true)}<p class="muted">Tarifas de envío e impuestos simulados. Disponibilidad y recetas pendientes de validación. Ninguna fecha queda reservada.</p><p id="reviewError" class="error" role="alert"></p><div class="checkout-actions"><button class="btn secondary" id="editDelivery2">← Editar entrega</button><button class="btn primary" id="makeMessage">Preparar WhatsApp ↗</button></div>`}
if(step===3){$('#checkoutContent').innerHTML=`<div class="success"><div class="success-icon">✓</div><h3>¡Su ritual ya tiene forma!</h3><p>Este es el mensaje que recibiría Perritual. Puedes copiarlo para revisar el flujo. <strong>No se ha enviado ningún mensaje.</strong></p><pre class="message-preview" id="messageText"></pre><p class="muted">Pedido de demostración · Sin número de WhatsApp conectado · Sin reserva ni pago.</p><div class="checkout-actions"><button class="btn secondary" id="backReview">← Revisar pedido</button><button class="btn primary" id="copyMessage">Copiar mensaje</button></div><button class="text-button" data-close="checkoutDialog" style="margin-top:20px">Seguir explorando Perritual</button></div>`;$('#messageText').textContent=buildMessage()}$('#checkoutDialog').scrollTop=0}
function buildMessage(){const t=Rules.totals(cart,delivery);return `¡Hola, Perritual! ♡\nQuiero celebrar con ustedes.\n\nPEDIDO DE DEMOSTRACIÓN — NO ES UNA COMPRA\n\n${cart.map(i=>`${i.qty} × ${Catalog.find(p=>p.id===i.id).name}\n${itemDescription(i)}\n${Money(Rules.unit(i)*i.qty)}`).join('\n\n')}\n\n${delivery.mode==='delivery'?'Domicilio: '+delivery.city+' · '+delivery.address:'Recogida: punto por acordar'}\nFecha: ${delivery.date}, ${delivery.time} (Colombia)\nNombre: ${delivery.name}\nCelular: ${delivery.phone}${delivery.note?'\nNota: '+delivery.note:''}\n\nSubtotal: ${Money(t.subtotal)}\nDescuento demo: ${Money(t.discount)}\nEnvío: ${Money(t.shipping||0)}\nTotal estimado: ${Money(t.total)}\nImpuestos incluidos en precios de ejemplo.\n\nQuedo pendiente de confirmar disponibilidad, ingredientes, entrega y valor final.`}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.close){closeDialog($('#'+el.dataset.close));return}if(el.dataset.product){e.preventDefault();openProduct(el.dataset.product);return}if(el.dataset.filter){filter=el.dataset.filter;renderFilters();renderProducts();return}if(el.dataset.color){draft.color=el.dataset.color;$$('.swatch').forEach(b=>b.setAttribute('aria-pressed',b.dataset.color===draft.color));$('#colorName').textContent=draft.color;updateDraft();return}if(el.dataset.qty){const i=cart.find(i=>i.key===el.dataset.qty);if(i)i.qty=Math.min(20,Math.max(1,i.qty+Number(el.dataset.delta)));persist();renderCart();const next=$$('[data-qty]').find(b=>b.dataset.qty===el.dataset.qty&&b.dataset.delta===el.dataset.delta&&!b.disabled)||$$('[data-qty]').find(b=>b.dataset.qty===el.dataset.qty&&!b.disabled);next?.focus({preventScroll:true});return}if(el.dataset.remove){cart=cart.filter(i=>i.key!==el.dataset.remove);persist();renderCart();toast('Producto eliminado de la bolsa');return}if(el.dataset.edit){const i=cart.find(i=>i.key===el.dataset.edit);if(i)openProduct(i.id,i.key);return}if(el.dataset.goal!==undefined){
 const recommendation=Rules.recommendations(cart)[Number(el.dataset.goal)];if(!recommendation)return;
 const before=Rules.totals(cart);
 recommendation.lines.forEach(line=>{const existing=cart.find(i=>i.id===line.id&&JSON.stringify(i.options)===JSON.stringify(line.options));if(existing)existing.qty+=line.qty;else cart.push({key:crypto.randomUUID(),id:line.id,qty:line.qty,options:{...line.options}})});
 persist();renderCart();const after=Rules.totals(cart);
 toast(before.toFree>0&&after.toFree===0?'¡Logro alcanzado! Tu pedido tiene envío gratis.':'Complemento añadido. Actualizamos tu progreso.');
 const reward=$('#cartContent .reward');reward.setAttribute('tabindex','-1');reward.focus({preventScroll:true});reward.scrollIntoView({block:'nearest',behavior:document.documentElement.dataset.motion==='paused'?'instant':'smooth'});return;
}if(el.dataset.add){const i=cart.find(i=>i.id===el.dataset.add);if(i&&i.qty<20)i.qty++;else if(!i)cart.push({key:crypto.randomUUID(),id:el.dataset.add,qty:1,options:{}});persist();renderCart();toast('Galletas añadidas a su celebración');return}if(el.dataset.mode){syncDelivery();delivery.mode=el.dataset.mode;renderCheckout(1);return}switch(el.id){case'cartOpen':renderCart();openDialog($('#cartDialog'));break;case'resetSearch':filter='Todos';$('#search').value='';renderFilters();renderProducts();break;case'startCheckout':if(!cart.length)return;$('#cartDialog').close();renderCheckout(1);openDialog($('#checkoutDialog'));break;case'backToCart':syncDelivery();$('#checkoutDialog').close();renderCart();openDialog($('#cartDialog'));break;case'editDelivery':case'editDelivery2':renderCheckout(1);break;case'makeMessage':if(!Rules.validSlot(delivery.date,delivery.time)){renderCheckout(1);$('#deliveryError').textContent='El horario ya no cumple las 24 horas de anticipación. Selecciona otro.';return}renderCheckout(3);break;case'backReview':renderCheckout(2);break;case'copyMessage':try{await navigator.clipboard.writeText(buildMessage());toast('Mensaje de ejemplo copiado')}catch{const range=document.createRange();range.selectNodeContents($('#messageText'));getSelection().removeAllRanges();getSelection().addRange(range);toast('Seleccionamos el mensaje. Usa la opción Copiar de tu dispositivo.')}break}});
$('#search').addEventListener('input',renderProducts);renderFilters();renderProducts();persist();
